
// Universal Single Sign-On (SSO) Helper for .grimaldi.tv
(function autoSyncSharedCookies() {
  try {
    const cookies = document.cookie || "";
    const isVipCookie = cookies.includes("samPremiumAccess=yes") || cookies.includes("samResponsibleUseAccepted=yes");
    const emailMatch = cookies.match(/dgp_subscriber_email=([^;]+)/);
    
    if (isVipCookie) {
      localStorage.setItem('samPremiumAccess', 'yes');
      localStorage.setItem('samResponsibleUseAccepted', 'yes');
      if (emailMatch && emailMatch[1]) {
        localStorage.setItem('dgp_subscriber_email', decodeURIComponent(emailMatch[1]));
      }
    }
  } catch (err) {}
})();

window.grantGrimaldiVip = function(email) {
  try {
    if (email) {
      localStorage.setItem('dgp_subscriber_email', email);
      document.cookie = "dgp_subscriber_email=" + encodeURIComponent(email) + "; path=/; domain=.grimaldi.tv; max-age=31536000; SameSite=Lax";
    }
    localStorage.setItem('samPremiumAccess', 'yes');
    localStorage.setItem('samResponsibleUseAccepted', 'yes');
    document.cookie = "samPremiumAccess=yes; path=/; domain=.grimaldi.tv; max-age=31536000; SameSite=Lax";
    document.cookie = "samResponsibleUseAccepted=yes; path=/; domain=.grimaldi.tv; max-age=31536000; SameSite=Lax";

    if (email && window.saveMemberToSamBettors) {
      window.saveMemberToSamBettors(email);
    }
  } catch (err) {}
};



window.promptGrimaldiVipLogin = function() { if (window.openGrimaldiAuthModal) window.openGrimaldiAuthModal(); };


window.saveMemberToSamBettors = async function(email, isLifetime = false) {
  try {
    if (!email) return;
    const url = "https://qfldfzjqufynrpnjsgex.supabase.co/rest/v1/sam_bettors";
    const key = "sb_publishable_c-tljO1Nskf685RK4nWiJg_bbj06fuh";
    
    const payload = {
      username: email.toLowerCase().trim(),
      email: email.toLowerCase().trim(),
      is_vip: true,
      lifetime_access: !!isLifetime,
      subscription_status: isLifetime ? 'lifetime' : 'active',
      plan_type: isLifetime ? 'lifetime_unlimited' : 'monthly_20',
      updated_at: new Date().toISOString()
    };

    await fetch(url, {
      method: "POST",
      headers: {
        "apikey": key,
        "Authorization": "Bearer " + key,
        "Content-Type": "application/json",
        "Prefer": "resolution=merge-duplicates"
      },
      body: JSON.stringify(payload)
    });
  } catch (err) {
    console.warn("Failed to sync member to sam_bettors Supabase table:", err);
  }
};


window.saveSubscriberToSamBettors = async function(email, name) {
  try {
    if (!email) return;
    const url = "https://qfldfzjqufynrpnjsgex.supabase.co/rest/v1/sam_bettors";
    const key = "sb_publishable_c-tljO1Nskf685RK4nWiJg_bbj06fuh";
    
    // Upsert into sam_bettors table
    const payload = {
      username: email.toLowerCase().trim(),
      email: email.toLowerCase().trim(),
      name: name || email.split('@')[0],
      is_vip: true,
      subscription_status: 'active',
      updated_at: new Date().toISOString()
    };

    await fetch(url, {
      method: "POST",
      headers: {
        "apikey": key,
        "Authorization": "Bearer " + key,
        "Content-Type": "application/json",
        "Prefer": "resolution=merge-duplicates"
      },
      body: JSON.stringify(payload)
    });
  } catch (err) {
    console.warn("Failed to sync to sam_bettors Supabase table:", err);
  }
};


window.isGrimaldiVip = function() {
  try {
    const isAcceptedLocally = localStorage.getItem('samPremiumAccess') === 'yes' || localStorage.getItem('samResponsibleUseAccepted') === 'yes';
    const isAcceptedCookie = document.cookie.includes('samPremiumAccess=yes') || document.cookie.includes('samResponsibleUseAccepted=yes');
    return isAcceptedLocally || isAcceptedCookie;
  } catch (err) {
    return false;
  }
};

window.grantGrimaldiVip = function(email) {
    if (email && window.saveSubscriberToSamBettors) {
      window.saveSubscriberToSamBettors(email);
    }
  
  try {
    if (email) localStorage.setItem('dgp_subscriber_email', email);
    localStorage.setItem('samPremiumAccess', 'yes');
    localStorage.setItem('samResponsibleUseAccepted', 'yes');
    document.cookie = "samPremiumAccess=yes; path=/; domain=.grimaldi.tv; max-age=31536000; SameSite=Lax";
    document.cookie = "samResponsibleUseAccepted=yes; path=/; domain=.grimaldi.tv; max-age=31536000; SameSite=Lax";
  } catch (err) {}
};


window.unlockGate = function() {
  try {
    localStorage.setItem('samResponsibleUseAccepted', 'yes');
    document.cookie = "samResponsibleUseAccepted=yes; path=/; domain=.grimaldi.tv; max-age=31536000; SameSite=Lax";
  } catch (err) {}
  const gate = document.getElementById('patriotGate');
  if (gate) gate.classList.add('hidden');
};
